// Keep retired geometry available for previously purchased boards and saved work.
const replacements=new Map(['canal','observatory','coral-palace','bookshop'].map((id,i)=>[id,NATURE_JEWELRY_BOARDS[i]]));
export const RETIRED_BOARDS=ORIGINAL_ADVANCED_BOARDS.filter(b=>replacements.has(b.id));
export const ADVANCED_BOARDS=ORIGINAL_ADVANCED_BOARDS.map(b=>composeBoard(refineBoard(replacements.get(b.id)||b)));
